INSERT INTO `pt_profiles` (`id`, `user_id`, `bio`, `specialty`, `experience_years`, `location_pricing_note`, `certificate_url`, `demo_video_url`, `verification_status`) VALUES
(1, 2, 'HLV Thể hình chuyên nghiệp & Tăng cơ chuyên sâu. Đạt chứng chỉ NASM CPT quốc tế.', 'Tăng cơ, Giảm mỡ, Thể hình, Dinh dưỡng thể thao', 6, 'Dạy tại nhà phụ thu 20% tiền đi lại', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=aclHkVaku9U', 'VERIFIED'),
(2, 3, 'Cựu vận động viên Men Physique quốc gia, chuyên coaching tăng kích thước cơ bắp và định hình cơ thể săn chắc.', 'Tăng cơ Hypertrophy, Siết mỡ, Thể hình nam nữ', 5, 'Hỗ trợ học viên đo InBody định kỳ hàng tuần', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=aclHkVaku9U', 'VERIFIED'),
(3, 4, 'Hơn 7 năm dẫn dắt hàng trăm học viên cải thiện vóc dáng từ gầy ốm sang cơ bắp vạm vỡ.', 'Thể hình chuyên sâu, Tăng cơ không mỡ, Dinh dưỡng macro', 7, 'Cam kết đạt mục tiêu nếu theo sát thực đơn', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=aclHkVaku9U', 'VERIFIED'),
(4, 5, 'Chuyên phương pháp tập luyện Push-Pull-Legs tối ưu tăng cơ toàn diện.', 'Tăng cơ thể hình, Cắt nét cơ bụng, Tăng cân cho nam', 4, 'Giáo án cá nhân hóa theo từng buổi', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=aclHkVaku9U', 'VERIFIED'),
(5, 6, 'Huấn luyện viên thể hình thi đấu, kèm cặp siết cơ thi đấu và tạo khối cơ sắc nét.', 'Thể hình thi đấu, Siết cơ chuyên sâu, Bulking & Cutting', 8, 'Kèm 1-1 chuyên sâu', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=aclHkVaku9U', 'VERIFIED'),
(6, 7, 'Tập trung cải thiện ngực, vai, lưng xô chữ V cho học viên nam văn phòng.', 'Tăng cơ thân trên, Lưng xô chữ V, Ngực nở vai rộng', 5, 'Có phòng gym liên kết cao cấp', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=aclHkVaku9U', 'VERIFIED'),
(7, 8, 'Phương pháp tập tạ khoa học, không dùng thực phẩm chức năng tràn lan.', 'Tăng cơ tự nhiên, Thể hình cơ bản, Form tạ chuẩn', 3, 'Linh hoạt lịch tập tối', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=aclHkVaku9U', 'VERIFIED'),
(8, 9, 'Huấn luyện viên thể lực năng động, chuyên giáo án cường độ cao đốt mỡ và tăng cường sức bền hệ tuần hoàn.', 'Giảm mỡ cấp tốc, HIIT, Thể lực toàn thân', 4, 'Tặng kèm thực đơn giảm cân 4 tuần', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=sw_Rvhw2qf4', 'VERIFIED'),
(9, 10, 'Tận tâm, kiên nhẫn, chuyên các bài tập bảo vệ khớp gối cho người có chỉ số BMI cao muốn giảm cân an toàn.', 'Giảm mỡ bụng, Chỉnh tư thế cho người thừa cân, Tim mạch', 3, 'Khởi động kỹ và kiểm tra tim mạch trước mỗi buổi', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=sw_Rvhw2qf4', 'VERIFIED'),
(10, 11, 'Chuyên giảm mỡ toàn thân cho nữ giới, siết eo và đùi bằng Tabata và tạ chuông Kettlebell.', 'Giảm mỡ nữ, Tabata, Kettlebell, Đốt mỡ thừa', 5, 'Kèm sát thực đơn ăn uống mỗi bữa', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=sw_Rvhw2qf4', 'VERIFIED'),
(11, 12, 'Giảm cân khoa học không nhịn ăn, kết hợp Cardio ngắt quãng và bài tập kháng lực.', 'Giảm cân không nhịn ăn, Cardio ngắt quãng, Eat Clean', 4, 'Theo dõi chỉ số mỡ nội tạng hàng tuần', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=sw_Rvhw2qf4', 'VERIFIED'),
(12, 13, 'Chuyên giúp các bạn trẻ giảm từ 5 - 10kg mỡ thừa trong 8 đến 12 tuần an toàn.', 'Giảm mỡ sinh viên, Vóc dáng thon thả, Cardio vui vẻ', 3, 'Học phí ưu đãi cho sinh viên', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=sw_Rvhw2qf4', 'VERIFIED'),
(13, 14, 'Huấn luyện viên Bootcamp thể lực ngoài trời, đốt cháy tối đa calo mỗi buổi tập.', 'Bootcamp ngoài trời, Thể lực sức bền, Giảm mỡ siêu tốc', 6, 'Tập nhóm nhỏ hoặc cá nhân', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=sw_Rvhw2qf4', 'VERIFIED'),
(14, 15, 'Huấn luyện viên Calisthenics và chỉnh sửa tư thế cột sống, cải thiện gù lưng đau mỏi vai gáy cho dân công sở.', 'Calisthenics, Chỉnh sửa tư thế, Tăng thể lực, Đau vai gáy', 4, 'Dụng cụ xà và vòng treo mang theo tận nơi', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=IODxDxX7oi4', 'VERIFIED'),
(15, 16, 'Chuyên gia kỹ thuật Handstand (trồng chuối) và Muscle Up. Hướng dẫn kiểm soát nhóm cơ cốt lõi (Core) hoàn hảo.', 'Calisthenics nâng cao, Muscle Up, Handstand, Giãn cơ', 5, 'Phù hợp cả người mới tập từ hít xà cơ bản', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=IODxDxX7oi4', 'VERIFIED'),
(16, 17, 'Tập luyện ngoài trời hoặc tại nhà không cần tạ, tối ưu sức mạnh dẻo dai và phản xạ cơ bắp nhanh nhạy.', 'Street Workout, Sức mạnh tự thân, Sức bền cơ bắp', 3, 'Không gian tập thoáng mát ngoài công viên hoặc tại nhà', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=IODxDxX7oi4', 'VERIFIED'),
(17, 18, 'Kết hợp Calisthenics và bài tập kích hoạt thần kinh cơ để phục hồi chức năng vận động cho dân văn phòng ngồi nhiều.', 'Chỉnh sửa gù lưng, Thoát vị nhẹ, Calisthenics trị liệu', 6, 'Kiểm tra độ linh hoạt khớp trước khi tập', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=IODxDxX7oi4', 'VERIFIED'),
(18, 19, 'Xây dựng cơ bắp săn chắc không cần tạ nặng, kiểm soát toàn diện cơ thể trên xà đơn và xà kép.', 'Cơ bắp tự thân, Xà đơn xà kép, Kiểm soát trọng lượng', 4, 'Kèm kỹ thuật thở và bảo vệ khớp cổ tay', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=IODxDxX7oi4', 'VERIFIED'),
(19, 20, 'Chuyên đào tạo các bài skill Calisthenics: Front Lever, Planche, Human Flag.', 'Kỹ năng Calisthenics, Sức mạnh gân khớp, Core đỉnh cao', 5, 'Giáo án phân tầng từ cơ bản đến siêu cấp', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=IODxDxX7oi4', 'VERIFIED'),
(20, 21, 'Chuyên gia Powerlifting và phát triển sức mạnh tối đa (Squat, Bench, Deadlift). Đạt chứng chỉ NASM CPT quốc tế.', 'Powerlifting, Sức mạnh, Tăng cân, Bulking, Squat Bench Deadlift', 5, 'Trang bị đầy đủ đai lưng và bảo hộ đầu gối', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=bEv6CCg2BC8', 'VERIFIED'),
(21, 22, 'Vận động viên thi đấu Powerlifting chuyên nghiệp với kỷ lục tổng tạ trên 600kg. Chuyên chỉnh form chống chấn thương.', 'Sức mạnh bộc phát, Powerlifting thi đấu, Chỉnh form tạ nặng', 8, 'Kiểm soát an toàn 100% trong từng rep tạ nặng', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=bEv6CCg2BC8', 'VERIFIED'),
(22, 23, 'Đào tạo bài bản theo giáo trình quốc tế CSCS. Giúp học viên tăng cường sức mạnh toàn diện mà không lo chấn thương.', 'Strength & Conditioning, Tăng cơ tạ nặng, Deadlift an toàn', 6, 'Phân tích chuyển động qua video quay chậm', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=bEv6CCg2BC8', 'VERIFIED'),
(23, 24, 'Chuyên cải thiện kỹ thuật Squat sâu không đau lưng và nâng cao mức tạ 1RM.', 'Squat chuyên sâu, Mức tạ 1RM, Gia tăng sức mạnh', 4, 'Hỗ trợ học viên test 1RM định kỳ', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=bEv6CCg2BC8', 'VERIFIED'),
(24, 25, 'Tập trung xây dựng nền tảng sức mạnh thô và kích thích mật độ xương khớp cho nam giới tuổi 30+.', 'Sức mạnh nam giới 30+, Tăng mật độ xương, Tạ nặng an toàn', 7, 'Khởi động và kích hoạt khớp háng chuyên nghiệp', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=bEv6CCg2BC8', 'VERIFIED'),
(25, 26, 'Chuyên môn Deadlift và gia tăng sức kéo lưng dưới, khắc phục thói quen cong lưng.', 'Deadlift chuyên sâu, Sức kéo lưng dưới, Form tạ hoàn hảo', 5, 'Trang bị phấn tạ và dây kéo strap', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=bEv6CCg2BC8', 'VERIFIED'),
(26, 27, 'HLV chuyên sâu Giảm mỡ siết cơ nữ, Pilates, Yoga phục hồi và thon gọn vóc dáng sau sinh. Chứng chỉ Pilates Thụy Sĩ.', 'Giảm mỡ nữ, Yoga, Pilates, Giảm cân sau sinh, Dinh dưỡng Eat Clean', 4, 'Kèm tại nhà phụ thu 50k tiền di chuyển', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=v7AYKMP6rOE', 'VERIFIED'),
(27, 28, 'Hơn 5 năm giảng dạy Pilates Reformer cho phái nữ. Chuyên các bài tập siết eo, nâng cung mông và tạo đường cong mềm mại.', 'Pilates thảm & máy Reformer, Siết eo thon gọn, Định hình mông', 5, 'Có phòng tập studio riêng tư cao cấp', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=v7AYKMP6rOE', 'VERIFIED'),
(28, 29, 'Chứng chỉ 500h Yoga Alliance quốc tế. Giúp học viên giải tỏa stress công việc, thư giãn tâm trí và cơ thể dẻo dai.', 'Yoga trị liệu, Giảm căng thẳng, Dẻo dai cơ thể, Giãn cơ sâu', 3, 'Cung cấp tinh dầu thơm và thảm tập cao cấp', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=v7AYKMP6rOE', 'VERIFIED'),
(29, 30, 'Chuyên gia thể hình nữ giúp chị em phụ nữ sở hữu số đo 3 vòng chuẩn chỉnh, tự tin diện trang phục ôm sát.', 'Siết cơ bụng nữ, Tăng cơ mông đùi không to chân, Eat Clean', 4, 'Thiết kế giáo án riêng biệt cho từng tạng người nữ', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=v7AYKMP6rOE', 'VERIFIED'),
(30, 31, 'Huấn luyện viên Yoga nhiệt huyết, chuyên phục hồi căng cứng cơ bắp cho nhân viên ngồi máy tính kéo dài.', 'Yoga phục hồi chấn thương nhẹ, Giãn cơ văn phòng, Thư giãn', 2, 'Giờ tập linh hoạt vào buổi sáng sớm hoặc trưa', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=v7AYKMP6rOE', 'VERIFIED'),
(31, 32, 'Chuyên gia Pilates thon gọn bắp tay, rãnh bụng số 11 và chỉnh gù lưng cho phụ nữ hiện đại.', 'Pilates rãnh bụng 11, Chỉnh tư thế nữ, Thon gọn bắp tay', 6, 'Studio máy móc nhập khẩu Mỹ', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=v7AYKMP6rOE', 'VERIFIED'),
(32, 33, 'HLV Yoga Vinyasa và Hatha, giúp học viên tăng độ mở khớp hông và kéo giãn cột sống tối đa.', 'Yoga Vinyasa, Mở khớp hông, Dẻo dai cột sống, Thiền định', 5, 'Học viên được hướng dẫn thiền định cuối buổi', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=v7AYKMP6rOE', 'VERIFIED'),
(33, 34, 'HLV thể lực, Boxing, Kickfit cường độ cao đốt mỡ cấp tốc và phản xạ tự vệ. Hơn 7 năm kinh nghiệm tại Times City.', 'Kickfit, Boxing, Cardio đốt mỡ, Tự vệ, Tăng sức bền', 7, 'HLV chuẩn bị sẵn găng tay và đích đấm chất lượng cao', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=1bPEqY_4j-w', 'VERIFIED'),
(34, 35, 'Võ sĩ Muay Thai chuyên nghiệp, kết hợp đòn chân, gối, chỏ giúp học viên tăng phản xạ và tiêu hao calo thần tốc.', 'Muay Thai, Kickboxing, Kỹ năng tự vệ đường phố, Đốt mỡ', 6, 'Tập luyện an toàn, không va chạm gây chấn thương', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=1bPEqY_4j-w', 'VERIFIED'),
(35, 36, 'Chuyên môn Kickfit cho nữ giới và người làm việc căng thẳng, xả stress tối đa sau giờ làm việc.', 'Kickfit nữ giới, Xả stress, Phản xạ nhanh, Săn chắc toàn thân', 4, 'Dạy kèm tận nhà hoặc tại phòng gym tiện lợi', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=1bPEqY_4j-w', 'VERIFIED'),
(36, 37, 'Boxing phương Tây cổ điển, rèn luyện bộ pháp di chuyển chân nhịp nhàng và sức mạnh đòn tay.', 'Boxing cổ điển, Bộ pháp di chuyển, Tự vệ thực tế', 5, 'Có sàn đài tập luyện thực tế', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=1bPEqY_4j-w', 'VERIFIED'),
(37, 38, 'Kickboxing giảm mỡ eo hông và bắp chân, bài tập sôi động trên nền nhạc tạo hưng phấn.', 'Kickboxing theo nhạc, Giảm mỡ eo hông, Năng lượng tích cực', 3, 'Trang bị đầy đủ băng quấn tay bảo vệ khớp', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=1bPEqY_4j-w', 'VERIFIED'),
(38, 39, 'Cựu HLV đội tuyển đối kháng, chuyên huấn luyện kỹ năng thoát hiểm và tự vệ trong không gian hẹp.', 'Võ tự vệ cận chiến, Thoát hiểm, Bản lĩnh tự tin', 8, 'Giáo trình an toàn tuyệt đối cho người chưa từng tập võ', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=1bPEqY_4j-w', 'VERIFIED'),
(39, 40, 'Bác sĩ Y học thể thao kiêm HLV phục hồi chức năng, chuyên điều trị đau lưng, thoát vị đĩa đệm và lệch vẹo cột sống.', 'Phục hồi chức năng, Thoát vị đĩa đệm, Đau cột sống, Lệch xương chậu', 9, 'Phác đồ điều trị kết hợp bài tập trị liệu khoa học', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=IODxDxX7oi4', 'VERIFIED'),
(40, 41, 'Chuyên gia giải phóng mạc cơ (Myofascial Release) và khắc phục hội chứng cổ rùa, đau mỏi vai gáy văn phòng.', 'Hội chứng cổ rùa, Đau vai gáy văn phòng, Giải phóng mạc cơ', 6, 'Có dụng cụ con lăn Foam Roller và súng massage chuyên dụng', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=IODxDxX7oi4', 'VERIFIED'),
(41, 42, 'Chuyên chỉnh sửa chân vòng kiềng (chân chữ X, chữ O) và cân chỉnh dáng đi cho thanh thiếu niên.', 'Chân vòng kiềng chữ X chữ O, Chỉnh dáng đi, Phục hồi khớp gối', 5, 'Đo góc lệch khớp trước và sau khóa học', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=IODxDxX7oi4', 'VERIFIED'),
(42, 43, 'Huấn luyện viên phục hồi sau chấn thương đứt dây chằng chéo trước ACL và thoái hóa khớp gối sớm.', 'Phục hồi dây chằng ACL, Khớp gối thoái hóa, Tái hòa nhập thể thao', 7, 'Phối hợp cùng bác sĩ chỉnh hình của học viên', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=IODxDxX7oi4', 'VERIFIED'),
(43, 44, 'Phương pháp kéo giãn PNF và kích hoạt các nhóm cơ yếu nhằm triệt tiêu các cơn đau lưng dưới dai dẳng.', 'Kéo giãn PNF, Giảm đau lưng dưới, Kích hoạt cơ yếu', 4, 'Bài tập êm dịu, không gây đau buốt', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=IODxDxX7oi4', 'VERIFIED'),
(44, 45, 'Trị liệu hội chứng chèn ép thần kinh tọa và cải thiện độ linh hoạt của toàn bộ khớp háng.', 'Đau thần kinh tọa, Linh hoạt khớp háng, Giảm căng cứng thắt lưng', 5, 'Kèm tận tình từng cử động nhỏ', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=IODxDxX7oi4', 'VERIFIED'),
(45, 46, 'Chuyên gia tăng cân an toàn cho người gầy lâu năm, cơ địa khó hấp thụ. Xây dựng thực đơn dinh dưỡng chuẩn y khoa.', 'Tăng cân người gầy, Dinh dưỡng hấp thụ, Tăng cơ tự nhiên', 5, 'Kèm sổ tay công thức nấu ăn ngon miệng dễ tăng cân', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=aclHkVaku9U', 'VERIFIED'),
(46, 47, 'Huấn luyện viên thể dục vận động cho người trung niên và người cao tuổi, tăng cường tuần hoàn máu và huyết áp ổn định.', 'Thể dục người cao tuổi, Ổn định huyết áp, Vận động nhẹ nhàng', 6, 'Đo huyết áp trước và sau mỗi buổi tập', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=v7AYKMP6rOE', 'VERIFIED'),
(47, 48, 'Chuyên gia tập luyện cho mẹ bầu (Prenatal) và phục hồi cơ sàn chậu, tách cơ bụng sau sinh (Postnatal).', 'Tập luyện mẹ bầu, Phục hồi sau sinh, Tách cơ bụng diastasis recti', 4, 'Đạt chứng chỉ quốc tế huấn luyện phụ nữ mang thai', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=v7AYKMP6rOE', 'VERIFIED'),
(48, 49, 'HLV Fitness trẻ nhiệt huyết, tốt nghiệp Đại học Thể dục Thể thao, chuyên giảm mỡ cho thanh niên.', 'Giảm mỡ trẻ em, Thể thao học đường, Bơi lội', 2, 'Chờ ban quản trị xét duyệt hồ sơ', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=sw_Rvhw2qf4', 'PENDING'),
(49, 50, 'HLV Aerobic và Cardio nhóm, nộp chứng chỉ chờ xác minh.', 'Aerobic nhóm, Group X, Đốt mỡ vui nhộn', 1, 'Chờ kiểm tra bằng cấp chứng chỉ', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=sw_Rvhw2qf4', 'PENDING'),
(50, 51, 'Hồ sơ chứng chỉ chưa đạt chuẩn theo quy định hệ thống PT Connect.', 'Thể hình tự do, Tập luyện cá nhân', 3, 'Tài khoản bị tạm ngưng', 'https://storage.ptconnect.vn/certs/cert_nasam.jpg', 'https://www.youtube.com/watch?v=aclHkVaku9U', 'REJECTED');

