INSERT INTO `courses` (`id`, `pt_id`, `title`, `description`, `total_sessions`, `validity_days`, `base_price`, `status`) VALUES
(1, 1, 'Gói Tăng Cơ Chuyên Sâu 24 Buổi - HLV Cường', 'Tối ưu hóa phì đại cơ bắp Hypertrophy chuẩn khoa học cùng HLV Lê Hoàng Cường.', 24, 90, 7200000.00, 'ACTIVE'),
(2, 1, 'Khóa Đốt Mỡ Cấp Tốc HIIT 16 Buổi - HLV Cường', 'Đốt calo cường độ cao, thon gọn vóc dáng nhanh chóng cùng HLV Lê Hoàng Cường.', 16, 60, 4800000.00, 'ACTIVE'),
(3, 2, 'Khóa Đốt Mỡ Cấp Tốc HIIT 16 Buổi - HLV Nam', 'Đốt calo cường độ cao, thon gọn vóc dáng nhanh chóng cùng HLV Nguyễn Hoàng Nam.', 16, 60, 4800000.00, 'ACTIVE'),
(4, 2, 'Gói Calisthenics & Thể Hình Tự Thân 20 Buổi - HLV Nam', 'Làm chủ cơ thể với xà đơn, xà kép và các chuyển động thăng bằng cùng HLV Nguyễn Hoàng Nam.', 20, 90, 6000000.00, 'ACTIVE'),
(5, 3, 'Gói Calisthenics & Thể Hình Tự Thân 20 Buổi - HLV Huy', 'Làm chủ cơ thể với xà đơn, xà kép và các chuyển động thăng bằng cùng HLV Đặng Quốc Huy.', 20, 90, 6000000.00, 'ACTIVE'),
(6, 3, 'Gói Pilates Chỉnh Dáng & Cột Sống 20 Buổi - HLV Huy', 'Siết cơ bụng sâu, cân chỉnh lưng gù và tạo đường cong mềm mại cùng HLV Đặng Quốc Huy.', 20, 90, 8000000.00, 'ACTIVE'),
(7, 4, 'Gói Pilates Chỉnh Dáng & Cột Sống 20 Buổi - HLV Dũng', 'Siết cơ bụng sâu, cân chỉnh lưng gù và tạo đường cong mềm mại cùng HLV Bùi Anh Dũng.', 20, 90, 8000000.00, 'ACTIVE'),
(8, 4, 'Gói Boxing Thể Lực & Xả Stress 16 Buổi - HLV Dũng', 'Tập luyện phản xạ nhanh, xả stress và tăng sức bền tim mạch cùng HLV Bùi Anh Dũng.', 16, 60, 5600000.00, 'ACTIVE'),
(9, 5, 'Gói Boxing Thể Lực & Xả Stress 16 Buổi - HLV Trọng', 'Tập luyện phản xạ nhanh, xả stress và tăng sức bền tim mạch cùng HLV Trần Đình Trọng.', 16, 60, 5600000.00, 'ACTIVE'),
(10, 5, 'Khóa Phục Hồi Cột Sống & Đau Vai Gáy 12 Buổi - HLV Trọng', 'Khắc phục đau nhức vai gáy và thoát vị nhẹ cho dân văn phòng cùng HLV Trần Đình Trọng.', 12, 60, 4200000.00, 'ACTIVE'),
(11, 6, 'Khóa Phục Hồi Cột Sống & Đau Vai Gáy 12 Buổi - HLV Hùng', 'Khắc phục đau nhức vai gáy và thoát vị nhẹ cho dân văn phòng cùng HLV Nguyễn Văn Hùng.', 12, 60, 4200000.00, 'ACTIVE'),
(12, 6, 'Khóa Powerlifting Sức Mạnh Squat-Bench-Deadlift 24 Buổi - HLV Hùng', 'Nâng cao mức tạ tối đa 1RM và hoàn thiện kỹ thuật tạ nặng cùng HLV Nguyễn Văn Hùng.', 24, 90, 8400000.00, 'ACTIVE'),
(13, 7, 'Khóa Powerlifting Sức Mạnh Squat-Bench-Deadlift 24 Buổi - HLV Thành', 'Nâng cao mức tạ tối đa 1RM và hoàn thiện kỹ thuật tạ nặng cùng HLV Vũ Đức Thành.', 24, 90, 8400000.00, 'ACTIVE'),
(14, 7, 'Gói Tăng Cân Khỏe Đẹp Cho Người Gầy 16 Buổi - HLV Thành', 'Kết hợp thực đơn giàu dinh dưỡng và bài tập hấp thụ tối đa cùng HLV Vũ Đức Thành.', 16, 60, 5200000.00, 'ACTIVE'),
(15, 8, 'Gói Tăng Cân Khỏe Đẹp Cho Người Gầy 16 Buổi - HLV Anh', 'Kết hợp thực đơn giàu dinh dưỡng và bài tập hấp thụ tối đa cùng HLV Trần Tuấn Anh.', 16, 60, 5200000.00, 'ACTIVE'),
(16, 8, 'Khóa Yoga Dẻo Dai & Thư Giãn Tinh Thần 12 Buổi - HLV Anh', 'Giải tỏa căng thẳng tinh thần, dẻo dai cơ bắp và lưu thông khí huyết cùng HLV Trần Tuấn Anh.', 12, 60, 3800000.00, 'ACTIVE'),
(17, 9, 'Khóa Yoga Dẻo Dai & Thư Giãn Tinh Thần 12 Buổi - HLV Quân', 'Giải tỏa căng thẳng tinh thần, dẻo dai cơ bắp và lưu thông khí huyết cùng HLV Vũ Minh Quân.', 12, 60, 3800000.00, 'ACTIVE'),
(18, 9, 'Khóa Khởi Động Nhập Môn 12 Buổi - HLV Quân', 'Làm quen với phòng gym và thể lực nền tảng cùng HLV Vũ Minh Quân.', 12, 60, 3600000.00, 'ACTIVE'),
(19, 10, 'Khóa Khởi Động Nhập Môn 12 Buổi - HLV Mai', 'Làm quen với phòng gym và thể lực nền tảng cùng HLV Nguyễn Thị Mai.', 12, 60, 3600000.00, 'ACTIVE'),
(20, 10, 'Gói Tăng Cơ Chuyên Sâu 24 Buổi - HLV Mai', 'Tối ưu hóa phì đại cơ bắp Hypertrophy chuẩn khoa học cùng HLV Nguyễn Thị Mai.', 24, 90, 7200000.00, 'ACTIVE'),
