(23, 12, 'Khóa Đốt Mỡ Cấp Tốc HIIT 16 Buổi - HLV Yến', 'Đốt calo cường độ cao, thon gọn vóc dáng nhanh chóng cùng HLV Lê Hải Yến.', 16, 60, 4800000.00, 'ACTIVE'),
