INSERT INTO `reviews` (`id`, `booking_id`, `rating`, `comment`, `created_at`) VALUES
(1, 5, 5, 'HLV hướng dẫn rất tận tình, chỉnh form tạ tỉ mỉ không bị đau lưng.', '2026-11-15 10:30:00'),
(2, 6, 5, 'Buổi tập rất hiệu quả, bài tập đa dạng và nhịp độ vừa sức.', '2026-11-15 18:30:00'),
(3, 7, 4, 'Rất hài lòng, cơ bắp căng mỏi đúng nhóm cơ mục tiêu.', '2026-11-15 09:00:00'),
(4, 11, 5, 'Tập bài Burpee và Mountain Climbers rất đã, HLV Cường hướng dẫn nhịp thở cực kỳ chuẩn chỉnh.', '2026-11-19 15:05:00'),
(5, 12, 5, 'Bài tập The Hundred và Roll Up giãn cơ lưng rất dễ chịu, HLV Dũng hỗ trợ tận tình.', '2026-11-19 10:35:00');

