(1, 8, 52, 'Học viên có lịch công tác đột xuất, báo trước hơn 24 giờ', NULL, 'PROCESSED', '2026-11-10 14:00:00'),
(2, 9, 2, 'HLV bị sốt phát ban phải nghỉ khám bệnh, hoàn trả buổi tập kèm bồi thường 150k', '/app/static/uploads/don_thuoc.jpg', 'PROCESSED', '2026-11-11 15:30:00'),
(3, 13, 53, 'Học viên có lịch công tác đột xuất, báo trước hơn 24 giờ', NULL, 'PROCESSED', '2026-11-19 11:00:00'),
(4, 15, 5, 'Hệ thống ghi nhận hủy ca do điểm danh vắng mặt', '/app/static/uploads/don_xin_hoan_lich.jpg', 'RESOLVED', '2026-11-17 09:30:00');

INSERT INTO `booking_disputes` (`id`, `booking_id`, `sender_id`, `dispute_type`, `reason`, `evidence_url`, `counter_evidence_url`, `counter_argument`, `status`, `admin_notes`, `resolved_at`, `created_at`) VALUES
(1, 9, 52, 'PT_NO_SHOW', 'HLV hủy sát giờ tập gây ảnh hưởng đến lịch trình cá nhân của em', '/app/static/uploads/tin_nhan_huy_lich.png', '/app/static/uploads/giay_xac_nhan_benh_vien.png', 'Tôi đã gọi điện xin lỗi và nộp đơn thuốc của bệnh viện kèm bồi thường cho học viên', 'PENDING', 'Đang chờ Ban quản trị đối soát chứng từ y tế của HLV', NULL, '2026-11-11 16:00:00'),
(2, 14, 53, 'PT_NO_SHOW', 'Tôi có mặt tại phòng tập Cầu Giấy lúc 15h20 và chờ đến 16h00 nhưng HLV Cường không xuất hiện, gọi điện thoại không liên lạc được. Yêu cầu Ban quản trị kiểm tra camera và hoàn trả 01 buổi tập khả dụng vào gói tập.', '/app/static/uploads/evidence_letan_cho_hlv.jpg', NULL, NULL, 'PENDING', 'Đang mở thời hạn 48 giờ để HLV gửi văn bản giải trình đối chất.', NULL, '2026-11-19 18:00:00'),
(3, 15, 53, 'WRONG_ABSENT', 'Tôi có đến tập và check-in tại quầy lễ tân lúc 7h55, nhưng mạng wifi phòng tập lỗi khiến mã OTP không đồng bộ được trên ứng dụng, dẫn đến bị tính vắng mặt và trừ buổi tập vô lý.', '/app/static/uploads/bien_lai_checkin_letan.jpg', '/app/static/uploads/xac_nhan_hlv_dung.jpg', 'Tôi xác nhận học viên Nguyễn Văn A có mặt đúng giờ. Lúc đó mạng wifi tại cơ sở bị mất kết nối nên không thể đồng bộ mã OTP lên máy chủ. Đề nghị Admin hoàn lại buổi tập cho học viên.', 'RESOLVED_REFUND', 'Ban quản trị đã đối soát camera quầy lễ tân và xác nhận của HLV Bùi Anh Dũng. Phán quyết: Hủy ghi nhận vắng mặt, hoàn trả 01 buổi tập khả dụng cho học viên Nguyễn Văn A.', '2026-11-18 14:00:00', '2026-11-17 10:00:00');

INSERT INTO `workout_plans` (`id`, `enrollment_id`, `title`, `goal`, `start_date`, `end_date`, `created_at`) VALUES
(1, 1, 'Giáo án Tăng cơ Thể hình 4 Tuần - HLV Cường', 'Tối ưu phì đại cơ ngực và tay sau, hoàn thiện form Bench Press', '2026-11-01', '2026-11-30', '2026-11-01 10:00:00'),
(2, 2, 'Giáo án Pilates Chỉnh dáng Cột sống & Siết eo', 'Tạo rãnh bụng 11, thắt chặt khung chậu và khắc phục gù lưng', '2026-11-05', '2026-12-05', '2026-11-05 11:00:00'),
(3, 5, 'Giáo Án Pilates Mat Cân Bằng Cột Sống & Mở Khớp Hông (Tháng 1)', 'Mở khớp vai, kéo giãn cơ thắt lưng và thiết lập hơi thở lồng ngực chuẩn Pilates', '2026-11-01', '2026-11-30', '2026-11-01 10:00:00'),
(4, 5, 'Giáo Án Định Hình Đường Cong & Tăng Cường Khung Chậu (Tháng 2)', 'Tạo dáng chữ S tự nhiên, siết cơ sàn chậu và cải thiện tư thế đứng', '2026-12-01', '2026-12-31', '2026-11-01 11:00:00'),
(5, 10, 'Giáo Án HIIT & Tabata Đốt Mỡ Thần Tốc (Giai đoạn 1: Tuần 1 - 2)', 'Kích hoạt chuyển hóa trao đổi chất, tăng sức bền tim mạch và đốt mỡ toàn thân', '2026-11-01', '2026-11-15', '2026-11-01 10:00:00'),
(6, 10, 'Giáo Án Core & Siết Mỡ Tầng Sâu (Giai đoạn 2: Tuần 3 - 4)', 'Tối ưu hóa đốt calo sau tập (EPOC), hình thành múi bụng và tăng độ dẻo dai', '2026-11-16', '2026-11-30', '2026-11-01 11:00:00');

