INSERT INTO `chat_messages` (`id`, `sender_id`, `receiver_id`, `content`, `is_read`, `created_at`) VALUES
(1, 52, 2, 'Chào anh Cường, em vừa đăng ký khóa tập 12 buổi của anh ạ!', True, '2026-11-01 10:15:00'),
(2, 2, 52, 'Chào Minh Anh nhé! Anh rất vui được đồng hành cùng em. Em đã có kinh nghiệm tập gym trước đây chưa?', True, '2026-11-01 10:20:00'),
(3, 52, 2, 'Dạ em mới tập tạ đơn ở nhà một ít thôi ạ, form tạ còn chưa chuẩn lắm.', True, '2026-11-01 10:22:00'),
(4, 2, 52, 'Không sao em, buổi đầu tiên anh sẽ kiểm tra độ linh hoạt khớp và hướng dẫn em từ căn bản nhé!', True, '2026-11-01 10:25:00'),
(5, 52, 2, 'Dạ vâng anh, em đã đặt lịch buổi đầu tiên vào sáng mai rồi ạ.', True, '2026-11-01 10:28:00'),
(6, 2, 52, 'Anh vừa duyệt lịch rồi nhé. Em nhớ mang giày thể thao và bình nước nhé!', True, '2026-11-01 10:30:00'),
(7, 2, 53, 'Chào bạn Văn A! Mình đã lên xong giáo án HIIT đốt mỡ cho bạn ở mục Khóa của tôi rồi nhé. Bạn xem trước bài Burpee và Mountain Climbers nhé!', True, '2026-11-16 09:00:00'),
(8, 53, 2, 'Dạ em chào anh Cường, em vừa xem qua giáo án rồi ạ, rất chi tiết và có video dễ hiểu. Chiều mai mình tập ở cơ sở Cầu Giấy đúng không anh?', True, '2026-11-16 09:15:00'),
(9, 2, 53, 'Đúng rồi em nhé, em nhớ uống đủ nước trước 30 phút và mang giày chạy bộ chuyên dụng nhé. Hẹn gặp em!', True, '2026-11-16 09:20:00'),
(10, 53, 2, 'Vâng anh, em sẽ đến đúng giờ ạ!', True, '2026-11-16 09:25:00'),
(11, 5, 53, 'Chào bạn A, giáo án Pilates chỉnh dáng cột sống của bạn đã được cập nhật lộ trình 2 tháng. Buổi tới chúng ta sẽ tập trung vào nhóm cơ thắt lưng và mở khớp hông nhé.', True, '2026-11-15 14:00:00'),
(12, 53, 5, 'Dạ vâng anh Dũng, lưng em dạo này ngồi làm việc văn phòng nhiều bị mỏi, tập bài Pilates Roll Up thấy đỡ hẳn ạ.', True, '2026-11-15 14:30:00'),
(13, 5, 53, 'Tuyệt vời, buổi tới anh sẽ chỉnh thêm form bài The Hundred để cơ bụng sâu kích hoạt tốt hơn nữa nhé!', True, '2026-11-15 15:00:00');

-- 18. ĐỒNG BỘ CHỈ SỐ ĐÁNH GIÁ CỦA PT THEO REVIEWS THỰC TẾ (Thuộc tính dẫn xuất BCNF tính động)
-- (Chỉ số đánh giá được tính động qua VIEW v_pt_profile_details)
-- 19. ĐỒNG BỘ TRẠNG THÁI KHUNG GIỜ VỚI BOOKING
UPDATE `availability_slots` s
JOIN `bookings` b ON s.`pt_id` = b.`pt_id` AND s.`start_time` = b.`slot_start_time`
SET s.`status` = 'BOOKED'
WHERE b.`status` IN ('PENDING', 'CONFIRMED', 'COMPLETED');

UPDATE `availability_slots` s
JOIN `bookings` b ON s.`pt_id` = b.`pt_id` AND s.`start_time` = b.`slot_start_time`
SET s.`status` = 'AVAILABLE'
WHERE b.`status` = 'CANCELLED';